package com.networkmonitorpro.ui; import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import androidx.core.content.ContextCompat;import androidx.viewpager2.widget.ViewPager2;import com.google.android.material.bottomnavigation.BottomNavigationView;import com.networkmonitorpro.R;import com.networkmonitorpro.service.NetworkMonitorService;import com.networkmonitorpro.ui.adapter.PagerAdapter; public class MainActivity extends AppCompatActivity{ ActivityResultLauncher<String[]> perms; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main); perms=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(), r->startMonitor()); requestPermissions(); ViewPager2 vp=findViewById(R.id.viewPager); BottomNavigationView nav=findViewById(R.id.bottomNav); vp.setAdapter(new PagerAdapter(this)); nav.setOnItemSelectedListener(i->{int p=i.getItemId()==R.id.nav_notifier?1:i.getItemId()==R.id.nav_downloader?2:i.getItemId()==R.id.nav_settings?3:0; vp.setCurrentItem(p,true);return true;}); vp.registerOnPageChangeCallback(new ViewPager2.OnPageChangeCallback(){public void onPageSelected(int p){nav.getMenu().getItem(p).setChecked(true);}});} private void requestPermissions(){ if(Build.VERSION.SDK_INT>=33 && ContextCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED) perms.launch(new String[]{Manifest.permission.POST_NOTIFICATIONS,Manifest.permission.READ_PHONE_STATE}); else startMonitor(); } private void startMonitor(){Intent i=new Intent(this, NetworkMonitorService.class); if(Build.VERSION.SDK_INT>=26)startForegroundService(i); else startService(i);} }
